import{i as r,B as e,c as n,z as t,w as a,h as s}from"./worker-DS0Lzple.js";import{aI as l}from"./pagectx-hMNRRcvy.js";import"./index-BjOm120o.js";import"./vendor-D0Nwz3sC.js";import"./ai-BVuHkpd9.js";import"./chatFloat-CrwaKTpm.js";import"./tex-BtWj0xuV.js";import"./markdown-CGKQYOlj.js";import"./questionFigures-DLmrVvl0.js";import"./quizIntent-P943mtJO.js";import"./playbook-COv8BvR_.js";const o="/work/.pdfvec/pdfvec.py",i="/work/.pdfvec/job.json",f="/work/.pdfvec/out.pdf";async function c(c){if(!r())return{ok:!1,error:"Python 沙箱未就绪（先让用户启用并装载 AI 工程组件）"};const p=Array.isArray(c?.blocks)&&c.blocks.length>0,d=!(!c||!c.html),m=!(!c||!c.markdown);if(!c||!c.title||!p&&!d&&!m)return{ok:!1,error:"title 必填，且 blocks / html / markdown 三者至少给一个"};if(p&&c.blocks.length>400)return{ok:!1,error:"blocks 太多（>400）：拆成多份文档，别一次塞进来"};const _=["reportlab"];!p&&m&&_.push("markdown"),p||!d&&!m||_.push("lxml");const h=await async function(r){const e=await t('import importlib.util as u\nprint(",".join(p for p in '+JSON.stringify(r)+" if u.find_spec(p)))",15e3);if(!e.ok)return"沙箱执行失败："+String(e.error||"").slice(0,160);const n=String(e.output||"").trim().split(",").filter(Boolean),a=r.filter(r=>n.indexOf(r)<0);if(!a.length)return"";const l=((await s(a)).failed||[]).filter(r=>a.indexOf(r.name)>=0);return l.length?"装 "+l.map(r=>r.name).join("/")+" 失败："+String(l[0].error).slice(0,200):""}(_);if(h)return{ok:!1,error:h};const g=await e(),b=await n(o,{text:"#!/usr/bin/env python3\r\n# -*- coding: utf-8 -*-\r\n\"\"\"pdfvec.py — 沙箱内「矢量层」PDF 渲染引擎（2026-11-13）\r\n\r\n═══════════════════════════════════════════════════════════════════════════════\r\n它解决什么问题\r\n  站内原有的 app.doc.pdf 是「服务端 KaTeX 排版 → 整页栅格化」：公式最好看，但整页是\r\n  一张图片 —— 文字不能选中、不能检索、放大就糊、体积大。本引擎走另一条路：\r\n  **中文走 TTF 文字层，公式走矢量路径**，PDF 里一张图片都没有。\r\n\r\n技术底座（全部在沙箱里跑，不需要浏览器 / 不需要 DOM / 不需要原生二进制）\r\n  · reportlab   —— 排版引擎（Flowable / 文档模板 / 多遍构建 / 目录回填 / 绘图原语）\r\n  · matplotlib.TextPath —— 把 LaTeX（mathtext 子集）变成**贝塞尔轮廓**，原点在基线\r\n  · 自写状态机  —— 把 matplotlib 的逐点指令流翻译成 reportlab 的路径指令\r\n                  （MOVETO/LINETO/CURVE3/CURVE4/CLOSEPOLY；二次贝塞尔用精确公式升三次）\r\n\r\n关键不变量（改代码时别破坏）\r\n  ① 公式路径的 y=0 就是**基线** → 中文与公式共用一条基线，不需要垂直补偿；\r\n  ② 二次→三次用 C1=P0+2/3(Q-P0)、C2=P1+2/3(Q-P1)，**精确**而非采样 → 几何零误差；\r\n  ③ 行内混排里公式是**不可分割单元**（绝不从中间断行），中文按单字拆（才能精确换行）；\r\n  ④ 每行按该行最大 depth 动态加行距（分式的分母探到基线以下，不能压到下一行）；\r\n  ⑤ 自检：输出后自己数 /Subtype /Image —— 必须为 0（这是\"不是截图\"的唯一硬证据）。\r\n\r\n输入契约：一个 JSON（job），见 render_file() 的 doc 注释。\r\n输出：PDF 文件 + 一个 stats 字典（页数 / 曲线数 / 图片数 / 字节数）。\r\n═══════════════════════════════════════════════════════════════════════════════\r\n\"\"\"\r\n\r\nimport json\r\nimport os\r\nimport re\r\nimport sys\r\n\r\n# ── 依赖自检：缺了要给**可行动**的话，而不是 ImportError 堆栈 ──────────────────\r\ntry:\r\n    import matplotlib\r\n    matplotlib.use('Agg')\r\n    from matplotlib.font_manager import FontProperties, fontManager\r\n    from matplotlib.textpath import TextPath\r\nexcept Exception as _e:  # pragma: no cover\r\n    raise SystemExit('pdfvec: 缺少 matplotlib（先 py.loadPackage(\"matplotlib\")）：%s' % _e)\r\n\r\ntry:\r\n    from reportlab.lib import colors\r\n    from reportlab.lib.enums import TA_CENTER, TA_LEFT\r\n    from reportlab.lib.pagesizes import A4, B5, LETTER\r\n    from reportlab.lib.styles import ParagraphStyle\r\n    from reportlab.lib.units import mm\r\n    from reportlab.pdfbase import pdfmetrics\r\n    from reportlab.pdfbase.ttfonts import TTFont\r\n    from reportlab.pdfgen import canvas as rl_canvas\r\n    from reportlab.platypus import (\r\n        BaseDocTemplate, Flowable, Frame, KeepTogether, PageBreak, PageTemplate,\r\n        Paragraph, Spacer, Table, TableStyle,\r\n    )\r\n    from reportlab.platypus.tableofcontents import TableOfContents\r\nexcept Exception as _e:  # pragma: no cover\r\n    raise SystemExit('pdfvec: 缺少 reportlab（先 micropip.install(\"reportlab\")）：%s' % _e)\r\n\r\n\r\n# ══════════════════════════════════════════════════════════════════════════\r\n# 0. 常量与工具\r\n# ══════════════════════════════════════════════════════════════════════════\r\nPAPERS = {'A4': A4, 'B5': B5, 'Letter': LETTER, '16K': (184 * mm, 260 * mm)}\r\n\r\n# mathtext 只吃 LaTeX 子集：这些写法在 mathtext 里会炸或排版错乱，先挡在门外并给出替代\r\nUNSUPPORTED = [\r\n    (r'\\\\begin\\{', 'mathtext 不支持 \\\\begin{} 环境（cases/matrix 等）'),\r\n    (r'\\\\ce\\{', '化学式 \\\\ce{} 需要 mhchem 扩展，mathtext 不支持'),\r\n    (r'\\\\cancel', '\\\\cancel 不支持'),\r\n    (r'\\\\text\\{[^}]*[\\u4e00-\\u9fff]', '公式内中文请改用普通文字段落'),\r\n]\r\n\r\n\r\n# mathtext 与完整 LaTeX 的别名差异：这些写法在 mathtext 里会解析失败或不是同一个命令。\r\n# 只做**确定等价**的替换（`\\le`→`\\leq` 是同一个符号），不做任何\"猜用户想写什么\"的改动。\r\nTEX_NORMALIZE = [\r\n    (r'\\\\le(?![a-zA-Z])', r'\\\\leq'),\r\n    (r'\\\\ge(?![a-zA-Z])', r'\\\\geq'),\r\n    (r'\\\\ne(?![a-zA-Z])', r'\\\\neq'),\r\n    # \\frac 的两字符简写（\\frac12 / \\frac1n / \\fraca1）：mathtext 直接解析失败，\r\n    # 补成 \\frac{..}{..} 是**等价改写**，不改语义；三字符以上不动（可能是 \\frac123 这种真错）。\r\n    (r'\\\\frac\\s*([0-9A-Za-z])\\s*([0-9A-Za-z])(?![0-9A-Za-z])', r'\\\\frac{\\1}{\\2}'),\r\n]\r\n\r\n\r\n\r\ndef normalize_tex(tex):\r\n    out = tex or ''\r\n    for pat, rep in TEX_NORMALIZE:\r\n        out = re.sub(pat, rep, out)\r\n    return out\r\n\r\n\r\ndef warn_unsupported(tex):\r\n    \"\"\"返回该公式的第一个已知不支持原因（空串 = 没发现问题）。\"\"\"\r\n    for pat, why in UNSUPPORTED:\r\n        if re.search(pat, tex or ''):\r\n            return why\r\n    return ''\r\n\r\n\r\ndef esc_xml(s):\r\n    return (str(s or '').replace('&', '&amp;').replace('<', '&lt;')\r\n            .replace('>', '&gt;').replace('\"', '&quot;'))\r\n\r\n\r\n# ══════════════════════════════════════════════════════════════════════════\r\n# 1. 字体：中文 TTF + 数学字体集\r\n# ══════════════════════════════════════════════════════════════════════════\r\nFONTS = {'cn': 'CN', 'mono': 'Mono', 'mathset': 'cm'}\r\n_math_prop_cache = {}\r\n\r\n\r\ndef setup_fonts(cn_path, mono_path, mathset, katex_dir):\r\n    \"\"\"注册中文字体与等宽字体；准备数学字体集（cm 默认 / katex 可选）。\r\n\r\n    ★ 为什么数学字体集要单独讲：\r\n      matplotlib 默认 mathtext.fontset='dejavusans' —— 无衬线通用字体，笔画粗细均匀、\r\n      没有数学斜体的倾斜与衬线细节，出来的公式\"不像教科书公式\"（对，就是看着怪）。\r\n      实测：设 `plt.rcParams['mathtext.fontset']='cm'` 对 TextPath **无效**（顶点数不变），\r\n      字体集由 **FontProperties** 携带。所以这里两级都设，并用顶点数自检是否真的生效。\r\n    \"\"\"\r\n    ok = {}\r\n    if cn_path and os.path.exists(cn_path):\r\n        try:\r\n            pdfmetrics.registerFont(TTFont('CN', cn_path))\r\n            ok['cn'] = True\r\n        except Exception:\r\n            ok['cn'] = False\r\n    if not ok.get('cn'):\r\n        # 退化：至少不崩（中文会缺字，回执里会如实说明）\r\n        FONTS['cn'] = 'Helvetica'\r\n        ok['cn'] = False\r\n    if mono_path and os.path.exists(mono_path):\r\n        try:\r\n            pdfmetrics.registerFont(TTFont('Mono', mono_path))\r\n            ok['mono'] = True\r\n        except Exception:\r\n            FONTS['mono'] = 'Courier'\r\n    else:\r\n        FONTS['mono'] = 'Courier'\r\n\r\n    # KaTeX 真字体（可选）：把 ttf 注册进 matplotlib 的字体表，供 custom 字体集使用\r\n    katex_ok = False\r\n    if mathset == 'katex' and katex_dir and os.path.isdir(katex_dir):\r\n        faces = {\r\n            'KaTeX_Main-Regular.ttf': 'KaTeX_Main',\r\n            'KaTeX_Main-Bold.ttf': 'KaTeX_Main',\r\n            'KaTeX_Main-Italic.ttf': 'KaTeX_Main',\r\n            'KaTeX_Math-Italic.ttf': 'KaTeX_Math',\r\n            'KaTeX_AMS-Regular.ttf': 'KaTeX_AMS',\r\n        }\r\n        for fn in faces:\r\n            p = os.path.join(katex_dir, fn)\r\n            if os.path.exists(p):\r\n                try:\r\n                    fontManager.addfont(p)\r\n                except Exception:\r\n                    pass\r\n        try:\r\n            matplotlib.rcParams['mathtext.fontset'] = 'custom'\r\n            matplotlib.rcParams['mathtext.rm'] = 'KaTeX_Main'\r\n            matplotlib.rcParams['mathtext.it'] = 'KaTeX_Math:italic'\r\n            matplotlib.rcParams['mathtext.bf'] = 'KaTeX_Main:bold'\r\n            matplotlib.rcParams['mathtext.cal'] = 'KaTeX_Caligraphic'\r\n            matplotlib.rcParams['mathtext.sf'] = 'KaTeX_SansSerif'\r\n            matplotlib.rcParams['mathtext.fallback'] = 'stix'\r\n            katex_ok = True\r\n        except Exception:\r\n            katex_ok = False\r\n    FONTS['mathset'] = 'katex' if katex_ok else 'cm'\r\n    return {'cn': bool(ok.get('cn')), 'mono': True, 'mathset': FONTS['mathset']}\r\n\r\n\r\ndef math_prop(size):\r\n    \"\"\"取一个带字体集信息的 FontProperties（按尺寸缓存，TextPath 很贵）。\"\"\"\r\n    key = round(float(size), 2)\r\n    fp = _math_prop_cache.get(key)\r\n    if fp is None:\r\n        fp = FontProperties(family='DejaVu Sans', size=key)\r\n        try:\r\n            fp.set_math_fontfamily(FONTS['mathset'])\r\n        except Exception:\r\n            pass\r\n        _math_prop_cache[key] = fp\r\n    return fp\r\n\r\n\r\n# ══════════════════════════════════════════════════════════════════════════\r\n# 2. TextPath → reportlab 路径（核心：逐点指令流 → 三次贝塞尔）\r\n# ══════════════════════════════════════════════════════════════════════════\r\n_tp_cache = {}\r\n\r\n\r\ndef textpath(tex, size):\r\n    \"\"\"(缓存) LaTeX → TextPath。TextPath 的原点就在**基线**上（这是同基线混排的地基）。\"\"\"\r\n    tex = normalize_tex(tex)\r\n    key = (tex, round(float(size), 2), FONTS['mathset'])\r\n    tp = _tp_cache.get(key)\r\n    if tp is None:\r\n        tp = TextPath((0, 0), '$' + tex + '$', size=float(size), prop=math_prop(size))\r\n        _tp_cache[key] = tp\r\n    return tp\r\n\r\n\r\ndef safe_textpath(tex, size, warn=None):\r\n    \"\"\"取 TextPath，失败返回 None 并记一条可定位的警告。\r\n\r\n    ★ 为什么不能让异常冒出去：一条坏公式不该毁掉整份讲义。mathtext 只吃 LaTeX 子集，\r\n      `\\\\begin{cases}` / `\\\\ce{}` / 少个括号都会 ParseFatalException —— 冒出去的结果是\r\n      **整份 PDF 一个字都出不来**，而用户只写错了一个公式。这里降级成文字渲染，\r\n      并把\"哪个公式、为什么\"记进 stats.warnings，回执原样带给模型/用户。\r\n    \"\"\"\r\n    try:\r\n        return textpath(tex, size)\r\n    except Exception as e:\r\n        if warn is not None:\r\n            warn.append('公式降级为文字：%s —— %s' % (str(tex)[:48], str(e).split('\\n')[0][:80]))\r\n        return None\r\n\r\n\r\ndef tp_metrics(tp):\r\n    \"\"\"→ (宽度, 基线以上高度, 基线以下深度)。\r\n\r\n    为什么三个都要：宽度决定光标推进与换行；asc 决定行高；**desc 决定行距**\r\n    （分式的分母会探到基线以下，不按 depth 加行距就会压到下一行）。\r\n    \"\"\"\r\n    try:\r\n        x0, y0, x1, y1 = tp.get_extents().extents\r\n    except Exception:\r\n        x0 = y0 = 0.0\r\n        x1, y1 = 1.0, 1.0\r\n    return (max(0.0, x1) + 0.7, max(0.0, y1), max(0.0, -y0))\r\n\r\n\r\ndef draw_tp(c, tp, x, y):\r\n    \"\"\"把一条 TextPath 画到 canvas 的 (x, y=基线)。返回画出的曲线条数。\r\n\r\n    逐点翻译（不是\"按三个点一组猜\"）：matplotlib 的 iter_segments() 给的是**逐个控制点**，\r\n    编码序列里会出现 [3,3,2]、[3,79,1] 这种不构成三连的情况（二次曲线混在三次里），\r\n    所以必须用状态机：CURVE3 要**两个点**凑一条二次曲线，再升成三次。\r\n    \"\"\"\r\n    verts = tp.vertices\r\n    codes = tp.codes\r\n    n = len(codes)\r\n    i = 0\r\n    prev = None\r\n    ctrl = None\r\n    curves = 0\r\n    c.saveState()\r\n    c.translate(x, y)\r\n    p = c.beginPath()\r\n    pt = lambda k: (float(verts[k][0]), float(verts[k][1]))\r\n    while i < n:\r\n        cd = int(codes[i])\r\n        if cd == 1:                      # MOVETO\r\n            prev = pt(i)\r\n            p.moveTo(prev[0], prev[1])\r\n            ctrl = None\r\n            i += 1\r\n        elif cd == 2:                    # LINETO\r\n            prev = pt(i)\r\n            p.lineTo(prev[0], prev[1])\r\n            ctrl = None\r\n            i += 1\r\n        elif cd == 3:                    # CURVE3：二次，两点一条\r\n            q = pt(i)\r\n            if ctrl is None:\r\n                ctrl = q\r\n                i += 1\r\n            else:\r\n                p0 = prev or q\r\n                c1 = (p0[0] + 2.0 / 3.0 * (ctrl[0] - p0[0]), p0[1] + 2.0 / 3.0 * (ctrl[1] - p0[1]))\r\n                c2 = (q[0] + 2.0 / 3.0 * (ctrl[0] - q[0]), q[1] + 2.0 / 3.0 * (ctrl[1] - q[1]))\r\n                p.curveTo(c1[0], c1[1], c2[0], c2[1], q[0], q[1])\r\n                curves += 1\r\n                prev = q\r\n                ctrl = None\r\n                i += 1\r\n        elif cd == 4:                    # CURVE4：三次，三点一条\r\n            if i + 2 < n:\r\n                a, b, e = pt(i), pt(i + 1), pt(i + 2)\r\n                p.curveTo(a[0], a[1], b[0], b[1], e[0], e[1])\r\n                curves += 1\r\n                prev = e\r\n                i += 3\r\n            else:\r\n                i += 1\r\n        elif cd == 79:                   # CLOSEPOLY\r\n            p.close()\r\n            i += 1\r\n        else:\r\n            i += 1\r\n    c.drawPath(p, stroke=0, fill=1)\r\n    c.restoreState()\r\n    return curves\r\n\r\n\r\n# ══════════════════════════════════════════════════════════════════════════\r\n# 3. 行内混排（中文按字 / 公式整体 / 不可断行）\r\n# ══════════════════════════════════════════════════════════════════════════\r\nTOKEN_RE = re.compile(r'(\\$[^$]+\\$|\\*\\*[^*]+\\*\\*)')\r\n\r\n# 不能出现在行首的标点（简化版「避头点 / 禁则」）。\r\n# 为什么必须有：中文是按**单字**拆行换行的，句号/逗号于是很容易被顶到下一行开头，\r\n# 截图复核时看到「……最值定理）。」的句号孤零零占了半行 —— 中文排版里这是硬伤。\r\nNO_LINE_START = set('，。、；：？！）》」』】,.;:?!)]}％·…—')\r\n\r\n\r\ndef _is_no_start(tok):\r\n    return bool(tok) and tok[0] in NO_LINE_START\r\n\r\n\r\ndef split_tokens(text):\r\n    \"\"\"把一段文字拆成 token 序列：[('t', 文字) | ('m', tex) | ('b', 强调文字)]。\r\n\r\n    ★ 中文按**单字**拆、公式按**整体**：中文等宽无空格，按字拆才能精确换行；\r\n    公式绝不能从中间断（$\\\\frac{}{}$ 被切两半就是废纸）。\r\n    ★ `**强调**` 单独成 token：这套字体没有第二个字重可切，用强调色近似（比把星号漏出来强）。\r\n    \"\"\"\r\n    out = []\r\n    for part in TOKEN_RE.split(str(text or '')):\r\n        if not part:\r\n            continue\r\n        if part.startswith('$') and part.endswith('$') and len(part) > 2:\r\n            out.append(('m', part[1:-1]))\r\n        elif part.startswith('**') and part.endswith('**') and len(part) > 4:\r\n            out.append(('b', part[2:-2]))\r\n        else:\r\n            for ch in part:\r\n                out.append(('t', ch))\r\n    return out\r\n\r\n\r\nclass Rich(Flowable):\r\n    \"\"\"行内混排段落：中文文字层 + 公式矢量路径，**同一条基线**。\r\n\r\n    为什么不用 Paragraph：reportlab 的 Paragraph 只会画字，插不进矢量路径；\r\n    而公式必须是路径（这是\"文字层 + 矢量\"方案的核心）。所以自己实现一个 Flowable：\r\n      wrap() 里贪心换行并记住每行最大 depth；draw() 里逐字 drawString、逐公式 draw_tp。\r\n    \"\"\"\r\n\r\n    def __init__(self, text, *, font=None, size=10.5, leading=None, color=None,\r\n                 align='left', indent=0, stats=None, warn=None):\r\n        Flowable.__init__(self)\r\n        self.warn = warn\r\n        self.text = text\r\n        self.font = font or FONTS['cn']\r\n        self.size = float(size)\r\n        self.base_leading = float(leading or size * 1.62)\r\n        self.color = color\r\n        self.align = align\r\n        self.indent = float(indent)\r\n        self.stats = stats if stats is not None else {'curves': 0, 'formulas': 0}\r\n        self._lines = []\r\n\r\n    # -------- 度量 --------\r\n    def _tok_w(self, kind, val):\r\n        if kind in ('t', 'b'):\r\n            return pdfmetrics.stringWidth(val, self.font, self.size)\r\n        if kind == 'm':\r\n            tp = safe_textpath(val, self.size, self.warn)\r\n            if tp is None:\r\n                return pdfmetrics.stringWidth(val, self.font, self.size)\r\n            return tp_metrics(tp)[0]\r\n        return pdfmetrics.stringWidth(val, self.font, self.size)\r\n\r\n    def _layout(self, avail):\r\n        avail = max(20.0, avail - self.indent)\r\n        toks = split_tokens(self.text)\r\n        lines = []\r\n        cur = []\r\n        cur_w = 0.0\r\n        cur_depth = 0.0\r\n        for kind, val in toks:\r\n            if kind in ('t', 'b'):\r\n                if val == '\\n':\r\n                    lines.append((cur, cur_w, cur_depth))\r\n                    cur, cur_w, cur_depth = [], 0.0, 0.0\r\n                    continue\r\n                w = self._tok_w(kind, val)\r\n                if cur_w + w > avail and cur:\r\n                    if _is_no_start(val):\r\n                        # 避头点：标点不许顶行首 → 挤在本行末尾（略超出，比孤零零一个句号好看）\r\n                        cur.append((kind, val, w))\r\n                        cur_w += w\r\n                        lines.append((cur, cur_w, cur_depth))\r\n                        cur, cur_w, cur_depth = [], 0.0, 0.0\r\n                        continue\r\n                    lines.append((cur, cur_w, cur_depth))\r\n                    cur, cur_w, cur_depth = [], 0.0, 0.0\r\n                    if val == ' ':\r\n                        continue\r\n                cur.append((kind, val, w))\r\n                cur_w += w\r\n            else:\r\n                tp = safe_textpath(val, self.size, self.warn)\r\n                if tp is None:\r\n                    # 降级：按普通文字排，宽度按字符串算（不画路径，不会丢内容）\r\n                    w = pdfmetrics.stringWidth(val, self.font, self.size)\r\n                    depth = 0.0\r\n                    if cur_w + w > avail and cur:\r\n                        lines.append((cur, cur_w, cur_depth))\r\n                        cur, cur_w, cur_depth = [], 0.0, 0.0\r\n                    cur.append(('t', val, w))\r\n                    cur_w += w\r\n                    continue\r\n                w = tp_metrics(tp)[0]\r\n                depth = tp_metrics(tp)[2]\r\n                if cur_w + w > avail and cur:\r\n                    lines.append((cur, cur_w, cur_depth))\r\n                    cur, cur_w, cur_depth = [], 0.0, 0.0\r\n                cur.append((kind, val, w))\r\n                cur_w += w\r\n                cur_depth = max(cur_depth, depth)\r\n        lines.append((cur, cur_w, cur_depth))\r\n        return lines\r\n\r\n    def wrap(self, availWidth, availHeight):\r\n        self._avail = availWidth\r\n        self._lines = self._layout(availWidth)\r\n        h = 0.0\r\n        for _toks, _w, depth in self._lines:\r\n            h += self.base_leading + depth\r\n        self.height = max(h, self.base_leading)\r\n        return (availWidth, self.height)\r\n\r\n    def draw(self):\r\n        c = self.canv\r\n        y = self.height\r\n        for toks, w, depth in self._lines:\r\n            line_h = self.base_leading + depth\r\n            y -= line_h\r\n            # 基线位置：整份 depth 都在基线以下，另留一点点呼吸位。\r\n            # （早先按 depth*0.42 折中，结果带分式的行整体偏下——截图复核出来的，改成 depth + 小间隙）\r\n            baseline = y + depth + self.size * 0.12\r\n            x = self.indent\r\n            if self.align == 'center':\r\n                x = self.indent + max(0.0, (self._avail - self.indent - w) / 2.0)\r\n            if self.color is not None:\r\n                c.setFillColor(self.color)\r\n            for kind, val, tw in toks:\r\n                if kind == 't':\r\n                    if val != ' ' or x > self.indent:\r\n                        c.setFont(self.font, self.size)\r\n                        c.drawString(x, baseline, val)\r\n                    x += tw\r\n                elif kind == 'b':\r\n                    # 强调：字体没有第二个字重，用强调色近似（整段换色比漏出 ** 星号强）\r\n                    c.setFont(self.font, self.size)\r\n                    c.setFillColor(colors.HexColor('#b91c1c'))\r\n                    c.drawString(x, baseline, val)\r\n                    c.setFillColor(self.color if self.color is not None else colors.black)\r\n                    x += tw\r\n                else:\r\n                    tp = safe_textpath(val, self.size, self.warn)\r\n                    if tp is None:\r\n                        c.setFont(self.font, self.size)\r\n                        c.drawString(x, baseline, val)\r\n                    else:\r\n                        self.stats['curves'] += draw_tp(c, tp, x, baseline)\r\n                        self.stats['formulas'] += 1\r\n                    x += tw\r\n\r\n\r\nclass FormulaBlock(Flowable):\r\n    \"\"\"独立公式（display）：居中/左对齐 + 可选编号 (1)(2)…，同样只画矢量路径。\"\"\"\r\n\r\n    def __init__(self, tex, *, size=12.5, number=None, align='center', stats=None, warn=None):\r\n        Flowable.__init__(self)\r\n        self.warn = warn\r\n        self.tex = tex\r\n        self.size = float(size)\r\n        self.number = number\r\n        self.align = align\r\n        self.stats = stats if stats is not None else {'curves': 0, 'formulas': 0}\r\n\r\n    def wrap(self, availWidth, availHeight):\r\n        self._avail = availWidth\r\n        self.tp = safe_textpath(self.tex, self.size, self.warn)\r\n        if self.tp is None:\r\n            self.height = self.size * 1.9\r\n            self._w = pdfmetrics.stringWidth(self.tex, FONTS['cn'], self.size)\r\n            return (availWidth, self.height)\r\n        w, asc, desc = tp_metrics(self.tp)\r\n        self._w, self._asc, self._desc = w, asc, desc\r\n        self.height = asc + desc + self.size * 0.62\r\n        return (availWidth, self.height)\r\n\r\n    def draw(self):\r\n        c = self.canv\r\n        if self.tp is None:\r\n            c.setFont(FONTS['cn'], self.size * 0.94)\r\n            c.drawCentredString(self._avail / 2.0, self.size * 0.6, self.tex)\r\n            return\r\n        base_y = self._desc + self.size * 0.32\r\n        x = 0.0\r\n        if self.align == 'center':\r\n            x = max(0.0, (self._avail - self._w) / 2.0)\r\n        self.stats['curves'] += draw_tp(c, self.tp, x, base_y)\r\n        self.stats['formulas'] += 1\r\n        if self.number:\r\n            c.setFont(FONTS['cn'], self.size * 0.82)\r\n            c.drawRightString(self._avail, base_y, '(%s)' % self.number)\r\n\r\n\r\n# ══════════════════════════════════════════════════════════════════════════\r\n# 4. 排版：样式、块 → Flowable、页眉页脚、目录\r\n# ══════════════════════════════════════════════════════════════════════════\r\n# ── 主题：一套 token 决定整份文档的观感（这是「复杂布局做不了」的一半答案）────────\r\n# 立场：CSS 布局引擎进不来（没有 DOM），但**版式设计**不该因此失业。\r\n# 这里把\"观感\"抽成 token，布局交给下面 5.6 节的布局原语（cols / side / card）。\r\nTHEMES = {\r\n    'classic':  {'accent': '#2b6cb0', 'h1': '#1f2937', 'rule': True,  'size': 1.0,\r\n                 'box': {'def': '#eef4fb', 'thm': '#eefaf1', 'proof': '#f5f6f8', 'eg': '#fdf8ec', 'tip': '#eef4fb', 'warn': '#fdeeee'}},\r\n    'magazine': {'accent': '#b91c1c', 'h1': '#111827', 'rule': False, 'size': 1.02,\r\n                 'box': {'def': '#fdf2f2', 'thm': '#f7f7f7', 'proof': '#fafafa', 'eg': '#fff7ed', 'tip': '#fdf2f2', 'warn': '#fef2f2'}},\r\n    'swiss':    {'accent': '#1d4ed8', 'h1': '#0f172a', 'rule': True,  'size': 0.98,\r\n                 'box': {'def': '#eff6ff', 'thm': '#f1f5f9', 'proof': '#f8fafc', 'eg': '#f0f9ff', 'tip': '#eff6ff', 'warn': '#fef2f2'}},\r\n    'notebook': {'accent': '#0f766e', 'h1': '#1c1917', 'rule': False, 'size': 1.03,\r\n                 'box': {'def': '#ecfdf5', 'thm': '#f0fdf4', 'proof': '#fafaf9', 'eg': '#fffbeb', 'tip': '#ecfdf5', 'warn': '#fef2f2'}},\r\n}\r\n\r\n\r\ndef theme_of(name, accent_override=''):\r\n    t = THEMES.get(str(name or 'classic'), THEMES['classic'])\r\n    if accent_override:\r\n        t = dict(t)\r\n        t['accent'] = accent_override\r\n    return t\r\n\r\n\r\ndef build_styles(accent, cn_size):\r\n    c = colors.HexColor(accent) if accent else colors.HexColor('#2b6cb0')\r\n    return {\r\n        'accent': c,\r\n        'cn_size': cn_size,\r\n        'h1': {'size': cn_size + 7.5, 'space_before': 16, 'space_after': 8},\r\n        'h2': {'size': cn_size + 4.0, 'space_before': 12, 'space_after': 6},\r\n        'h3': {'size': cn_size + 1.6, 'space_before': 9, 'space_after': 4},\r\n        'p': {'size': cn_size, 'leading': cn_size * 1.62, 'space_after': 5},\r\n        'small': {'size': cn_size - 1.4, 'leading': (cn_size - 1.4) * 1.7},\r\n    }\r\n\r\n\r\nclass Doc(BaseDocTemplate):\r\n    \"\"\"带目录/页眉/页脚/水印的文档模板。\r\n\r\n    页脚「第 N 页 / 共 M 页」：总页数只有排完才知道 → 用 NumberedCanvas 的\r\n    「延迟绘制」技巧（showPage 时不真翻页，把状态存起来，save 时拿到总数再逐页放回）。\r\n    \"\"\"\r\n\r\n    def __init__(self, filename, *, meta, styles, header_text='', footer=True,\r\n                 watermark='', margins=(18 * mm, 18 * mm, 20 * mm, 18 * mm)):\r\n        self.meta = meta or {}\r\n        self.styles = styles\r\n        self.header_text = header_text\r\n        self.footer = footer\r\n        self.watermark = watermark\r\n        l, r, t, b = margins\r\n        BaseDocTemplate.__init__(\r\n            self, filename, pagesize=meta.get('pagesize', A4),\r\n            leftMargin=l, rightMargin=r, topMargin=t, bottomMargin=b,\r\n            title=meta.get('title', ''), author=meta.get('author', ''),\r\n            subject=meta.get('subject', ''), creator='pdfvec (kaoyan-v2)',\r\n        )\r\n        frame = Frame(self.leftMargin, self.bottomMargin,\r\n                      self.width, self.height, id='body')\r\n        self.addPageTemplates([PageTemplate(id='main', frames=[frame], onPage=self._deco)])\r\n\r\n    # --- 页眉页脚水印（每页一次）---\r\n    def _deco(self, c, doc):\r\n        if self.meta.get('cover_first') and doc.page == 1:\r\n            return\r\n        c.saveState()\r\n        if self.watermark:\r\n            c.setFont(FONTS['cn'], 34)\r\n            try:\r\n                c.setFillColor(colors.Color(0.45, 0.45, 0.45, alpha=0.16))\r\n            except Exception:\r\n                c.setFillColor(colors.grey)\r\n            c.translate(doc.pagesize[0] / 2.0, doc.pagesize[1] / 2.0)\r\n            c.rotate(32)\r\n            c.drawCentredString(0, 0, self.watermark)\r\n        if self.header_text:\r\n            c.setFont(FONTS['cn'], 8.4)\r\n            c.setFillColor(colors.HexColor('#6b7280'))\r\n            c.drawString(doc.leftMargin, doc.pagesize[1] - 13 * mm, self.header_text)\r\n            c.setStrokeColor(colors.HexColor('#e5e7eb'))\r\n            c.setLineWidth(0.5)\r\n            c.line(doc.leftMargin, doc.pagesize[1] - 14.6 * mm,\r\n                   doc.pagesize[0] - doc.rightMargin, doc.pagesize[1] - 14.6 * mm)\r\n        c.restoreState()\r\n\r\n    # --- 目录条目（多遍构建时由 afterFlowable 通知）---\r\n    def afterFlowable(self, flowable):\r\n        lvl = getattr(flowable, '_toc_level', None)\r\n        if lvl is None:\r\n            return\r\n        text = getattr(flowable, '_toc_text', '')\r\n        key = 'h%d-%d' % (lvl, id(flowable))\r\n        self.canv.bookmarkPage(key)\r\n        self.notify('TOCEntry', (lvl, text, self.page, key))\r\n        self.canv.addOutlineEntry(text, key, level=max(0, lvl - 1), closed=False)\r\n\r\n\r\nclass NumberedCanvas(rl_canvas.Canvas):\r\n    \"\"\"延迟绘制页脚：先攒页面状态，最后拿到总页数再统一画「第 N 页 / 共 M 页」。\"\"\"\r\n\r\n    def __init__(self, *a, **kw):\r\n        rl_canvas.Canvas.__init__(self, *a, **kw)\r\n        self._saved = []\r\n\r\n    def showPage(self):\r\n        self._saved.append(dict(self.__dict__))\r\n        self._startPage()\r\n\r\n    def save(self):\r\n        total = len(self._saved)\r\n        for st in self._saved:\r\n            self.__dict__.update(st)\r\n            if getattr(self, '_pdf_footer', True):\r\n                self._draw_pager(total)\r\n            rl_canvas.Canvas.showPage(self)\r\n        rl_canvas.Canvas.save(self)\r\n\r\n    def _draw_pager(self, total):\r\n        w, _h = self._pagesize\r\n        self.saveState()\r\n        self.setFont(FONTS['cn'], 8.4)\r\n        self.setFillColor(colors.HexColor('#6b7280'))\r\n        self.drawCentredString(w / 2.0, 10 * mm, '第 %d 页 / 共 %d 页' % (self._pageNumber, total))\r\n        self.restoreState()\r\n\r\n\r\n# ══════════════════════════════════════════════════════════════════════════\r\n# 5. 块 → Flowable\r\n# ══════════════════════════════════════════════════════════════════════════\r\nBOX_KIND = {\r\n    'def': ('定义', '#2b6cb0', '#eef4fb'),\r\n    'thm': ('定理', '#2f855a', '#eefaf1'),\r\n    'proof': ('证明', '#4a5568', '#f5f6f8'),\r\n    'eg': ('例', '#b7791f', '#fdf8ec'),\r\n    'tip': ('提示', '#2b6cb0', '#eef4fb'),\r\n    'warn': ('注意', '#c53030', '#fdeeee'),\r\n}\r\n\r\n\r\nclass Builder:\r\n    def __init__(self, styles, *, variant='teacher', eqnum=False, warn=None):\r\n        self.S = styles\r\n        self.variant = variant\r\n        self.eqnum = eqnum\r\n        self.eq = 0\r\n        self.stats = {'curves': 0, 'formulas': 0}\r\n        # ★ 必须保住**同一个列表对象**：`warn or []` 在 warn 为空列表时会新建一个，\r\n        # 于是警告写进了孤儿列表，stats.warnings 永远是空的 —— 那正是\"公式全成了文字，\r\n        # 却一条警告都没有\"的根因（最坏的一种静默）。空列表也是 falsy，这里专门踩过。\r\n        self.warn = warn if warn is not None else []\r\n        self.section = ''\r\n\r\n    # ---- 小工具 ----\r\n    def rich(self, text, size=None, **kw):\r\n        return Rich(text, font=FONTS['cn'], size=size or self.S['p']['size'],\r\n                    leading=self.S['p']['leading'], stats=self.stats, warn=self.warn, **kw)\r\n\r\n    def heading(self, text, level):\r\n        size = self.S['h%d' % level]['size']\r\n        r = Rich(text, font=FONTS['cn'], size=size,\r\n                 leading=size * 1.5, color=self.S['accent'] if level == 1 else colors.HexColor('#1f2937'),\r\n                 stats=self.stats, warn=self.warn)\r\n        r._toc_level = level\r\n        r._toc_text = text\r\n        if level == 1:\r\n            self.section = text\r\n        return [Spacer(1, self.S['h%d' % level]['space_before']), r,\r\n                Spacer(1, self.S['h%d' % level]['space_after'])]\r\n\r\n    def table(self, head, rows, widths=None):\r\n        \"\"\"三线表。单元格用 Rich（不是 Paragraph）—— 否则表格里的 $...$ 会原样露源码，\r\n        而表格恰恰是公式最密集的地方之一（对照表/结论表）。\"\"\"\r\n        fs = self.S['p']['size'] - 0.5\r\n        data = []\r\n        if head:\r\n            data.append([Rich(str(h), font=FONTS['cn'], size=fs, leading=fs * 1.5,\r\n                               color=colors.HexColor('#1f2937'), stats=self.stats, warn=self.warn)\r\n                         for h in head])\r\n        for row in rows:\r\n            data.append([Rich(str(c), font=FONTS['cn'], size=fs, leading=fs * 1.5,\r\n                               stats=self.stats, warn=self.warn) for c in row])\r\n        t = Table(data, colWidths=widths, hAlign='LEFT', repeatRows=1 if head else 0)\r\n        st = [('VALIGN', (0, 0), (-1, -1), 'TOP'),\r\n              ('LEFTPADDING', (0, 0), (-1, -1), 5), ('RIGHTPADDING', (0, 0), (-1, -1), 5),\r\n              ('TOPPADDING', (0, 0), (-1, -1), 3.5), ('BOTTOMPADDING', (0, 0), (-1, -1), 3.5),\r\n              ('LINEBELOW', (0, 0), (-1, 0), 1.1, colors.HexColor('#374151')),\r\n              ('LINEBELOW', (0, -1), (-1, -1), 1.1, colors.HexColor('#374151'))]\r\n        if head and len(data) > 2:\r\n            st.append(('LINEBELOW', (0, 1), (-1, -2), 0.4, colors.HexColor('#e5e7eb')))\r\n        t.setStyle(TableStyle(st))\r\n        return [Spacer(1, 3), t, Spacer(1, 6)]\r\n\r\n    def box(self, kind, text, title=''):\r\n        label, fg, bg = BOX_KIND.get(kind, BOX_KIND['tip'])\r\n        bg = (self.S.get('box') or {}).get(kind) or bg      # 主题可以覆盖盒子底色\r\n        head = title or label\r\n        inner = [Rich(head, font=FONTS['cn'], size=self.S['p']['size'] * 0.92,\r\n                      leading=self.S['p']['size'] * 1.5, color=colors.HexColor(fg), stats=self.stats, warn=self.warn)] \\\r\n            if head else []\r\n        inner.append(self.rich(text))\r\n        t = Table([[inner]], colWidths=[None], hAlign='LEFT')\r\n        t.setStyle(TableStyle([\r\n            ('BACKGROUND', (0, 0), (-1, -1), colors.HexColor(bg)),\r\n            ('BOX', (0, 0), (-1, -1), 0.6, colors.HexColor(fg)),\r\n            ('LEFTPADDING', (0, 0), (-1, -1), 8), ('RIGHTPADDING', (0, 0), (-1, -1), 8),\r\n            ('TOPPADDING', (0, 0), (-1, -1), 6), ('BOTTOMPADDING', (0, 0), (-1, -1), 6),\r\n        ]))\r\n        return [Spacer(1, 4), t, Spacer(1, 7)]\r\n\r\n    def code(self, text, lang=''):\r\n        lines = str(text or '').split('\\n')\r\n        rows = [[Paragraph('<font name=\"%s\" size=\"%s\">%s</font>' % (\r\n            FONTS['mono'], self.S['p']['size'] - 1.0, esc_xml(ln) or '&nbsp;'),\r\n            ParagraphStyle('code', fontName=FONTS['mono'], fontSize=self.S['p']['size'] - 1.0,\r\n                           leading=(self.S['p']['size'] - 1.0) * 1.45))] for ln in lines]\r\n        t = Table(rows, colWidths=[None], hAlign='LEFT')\r\n        t.setStyle(TableStyle([\r\n            ('BACKGROUND', (0, 0), (-1, -1), colors.HexColor('#f6f8fa')),\r\n            ('BOX', (0, 0), (-1, -1), 0.4, colors.HexColor('#e1e4e8')),\r\n            ('LEFTPADDING', (0, 0), (-1, -1), 7), ('RIGHTPADDING', (0, 0), (-1, -1), 7),\r\n            ('TOPPADDING', (0, 0), (-1, -1), 5), ('BOTTOMPADDING', (0, 0), (-1, -1), 5),\r\n        ]))\r\n        return [Spacer(1, 3), t, Spacer(1, 6)]\r\n\r\n    # ---- 布局原语（5.6）：两栏 / 图文并排 / 卡片 ------------------------------\r\n    # 立场说明：沙箱里没有 CSS 引擎，`float`/`grid`/`flex` 这些**永远**不会生效；\r\n    # 但\"两栏、图片旁文、带底色的卡片\"这些**版式**本身是可做的 —— 用几何容器表达，\r\n    # 而不是用样式表。所以这里给三个原语，HTML 侧对应 .cols / aside / .card 约定。\r\n\r\n    def _sub(self, blocks):\r\n        \"\"\"把一个子块列表编成 flowable 列表（复用主 build，因此子块支持全部块类型）。\"\"\"\r\n        out = []\r\n        for b in blocks or []:\r\n            if isinstance(b, dict):\r\n                out.extend(self.build([b]))\r\n        return out\r\n\r\n    def cols(self, cols, widths=None, gap=10.0):\r\n        \"\"\"并排多栏（2~3 栏）。每栏内容是**块列表**，栏内正常流式排版。\r\n\r\n        与 CSS 的差别（必须承认）：不做等高、不做自动均衡、不会跨栏续排 ——\r\n        栏高由内容决定，短的那栏底部留白。要\"整篇文章分两栏流动\"得用文档模板的\r\n        双 Frame（本引擎未启用，因为与目录/页脚的多遍构建冲突）。\r\n        \"\"\"\r\n        cols = [c for c in (cols or []) if isinstance(c, list)]\r\n        if len(cols) < 2:\r\n            return self._sub(cols[0] if cols else [])\r\n        n = len(cols)\r\n        ws = list(widths or [])\r\n        if len(ws) != n or not all(isinstance(x, (int, float)) and x > 0 for x in ws):\r\n            ws = [1.0 / n] * n\r\n        total = float(sum(ws))\r\n        ws = [w / total for w in ws]\r\n        avail = self._avail()\r\n        col_w = [max(40.0, avail * w - gap * (n - 1) / n) for w in ws]\r\n        cells = [self._sub(c) or [Spacer(1, 1)] for c in cols]\r\n        t = Table([cells], colWidths=col_w, hAlign='LEFT')\r\n        t.setStyle(TableStyle([\r\n            ('VALIGN', (0, 0), (-1, -1), 'TOP'),\r\n            ('LEFTPADDING', (0, 0), (-1, -1), 0), ('RIGHTPADDING', (0, 0), (-1, -1), 0),\r\n            ('TOPPADDING', (0, 0), (-1, -1), 0), ('BOTTOMPADDING', (0, 0), (-1, -1), 0),\r\n            ('LEFTPADDING', (1, 0), (-1, -1), gap),\r\n        ]))\r\n        return [Spacer(1, 3), t, Spacer(1, 8)]\r\n\r\n    def side(self, aside, body, side='right', width=0.34, gap=10.0):\r\n        \"\"\"图文并排（= 浮动块）：一栏窄、一栏宽。side=left 时窄栏在左。\r\n\r\n        用途：公式/要点/小表放窄栏，正文放宽栏 —— 这就是排版里\"图旁文\"的做法，\r\n        而且**不会出现 CSS float 那种文字绕排断裂**（代价是不能真正绕排贴边）。\r\n        \"\"\"\r\n        aw = max(0.18, min(0.6, float(width or 0.34)))\r\n        avail = self._avail()\r\n        wide_w = avail * (1 - aw) - gap\r\n        narrow_w = avail * aw\r\n        narrow = self._sub(aside) or [Spacer(1, 1)]\r\n        wide = self._sub(body) or [Spacer(1, 1)]\r\n        cells = [[narrow, wide]] if side != 'left' else [[wide, narrow]]\r\n        ws = [narrow_w, wide_w] if side != 'left' else [wide_w, narrow_w]\r\n        t = Table(cells, colWidths=ws, hAlign='LEFT')\r\n        st = [('VALIGN', (0, 0), (-1, -1), 'TOP'),\r\n              ('LEFTPADDING', (0, 0), (-1, -1), 0), ('RIGHTPADDING', (0, 0), (-1, -1), 0),\r\n              ('TOPPADDING', (0, 0), (-1, -1), 0), ('BOTTOMPADDING', (0, 0), (-1, -1), 0)]\r\n        st.append(('RIGHTPADDING', (0, 0), (0, 0), gap) if side != 'left' else ('LEFTPADDING', (1, 0), (1, 0), gap))\r\n        t.setStyle(TableStyle(st))\r\n        return [Spacer(1, 3), t, Spacer(1, 8)]\r\n\r\n    def card(self, blocks, title='', tone='plain'):\r\n        \"\"\"带底色/边框的容器（可嵌套任意块，包括 cols/side）。\"\"\"\r\n        tone_bg = {'plain': '#f8fafc', 'accent': '#eef4fb', 'warn': '#fdeeee'}.get(tone, '#f8fafc')\r\n        border = {'plain': '#e2e8f0', 'accent': self._accent_hex(), 'warn': '#c53030'}.get(tone, '#e2e8f0')\r\n        inner = []\r\n        if title:\r\n            inner.append(Rich(title, font=FONTS['cn'], size=self.S['p']['size'] * 0.94,\r\n                              leading=self.S['p']['size'] * 1.5,\r\n                              color=colors.HexColor(border), stats=self.stats, warn=self.warn))\r\n            inner.append(Spacer(1, 3))\r\n        inner.extend(self._sub(blocks))\r\n        if not inner:\r\n            inner = [Spacer(1, 1)]\r\n        t = Table([[inner]], colWidths=[self._avail()], hAlign='LEFT')\r\n        t.setStyle(TableStyle([\r\n            ('BACKGROUND', (0, 0), (-1, -1), colors.HexColor(tone_bg)),\r\n            ('BOX', (0, 0), (-1, -1), 0.6, colors.HexColor(border)),\r\n            ('LEFTPADDING', (0, 0), (-1, -1), 9), ('RIGHTPADDING', (0, 0), (-1, -1), 9),\r\n            ('TOPPADDING', (0, 0), (-1, -1), 7), ('BOTTOMPADDING', (0, 0), (-1, -1), 7),\r\n        ]))\r\n        return [Spacer(1, 4), t, Spacer(1, 8)]\r\n\r\n    def _avail(self):\r\n        return float(getattr(self, '_frame_width', 0) or 0) or 460.0\r\n\r\n    def _accent_hex(self):\r\n        try:\r\n            return '#%02x%02x%02x' % (int(self.S['accent'].red * 255), int(self.S['accent'].green * 255), int(self.S['accent'].blue * 255))\r\n        except Exception:\r\n            return '#2b6cb0'\r\n\r\n    def bullet(self, items, ordered=False):\r\n        out = []\r\n        for i, it in enumerate(items):\r\n            mark = ('%d. ' % (i + 1)) if ordered else '· '\r\n            out.append(Rich(mark + str(it), font=FONTS['cn'], size=self.S['p']['size'],\r\n                            leading=self.S['p']['leading'], indent=10, stats=self.stats, warn=self.warn))\r\n            out.append(Spacer(1, 2))\r\n        out.append(Spacer(1, 3))\r\n        return out\r\n\r\n    # ---- 主循环：块列表 → story ----\r\n    def build(self, blocks, *, toc=True):\r\n        story = []\r\n        if toc:\r\n            pass  # TOC 占位由 render_file 在 read 到 {t:'toc'} 时插入\r\n        for b in blocks:\r\n            if not isinstance(b, dict):\r\n                continue\r\n            t = str(b.get('t') or b.get('type') or '').lower()\r\n            if t in ('h1', 'h2', 'h3'):\r\n                story += self.heading(str(b.get('text', '')), int(t[1]))\r\n            elif t in ('p', 'para', 'text'):\r\n                story += [self.rich(str(b.get('text', ''))), Spacer(1, self.S['p']['space_after'])]\r\n            elif t in ('formula', 'math'):\r\n                tex = str(b.get('tex') or b.get('text') or '').strip().strip('$')\r\n                why = warn_unsupported(tex)\r\n                if why:\r\n                    self.warn.append('公式被降级为文字：' + why)\r\n                    story += [self.rich(tex), Spacer(1, 6)]\r\n                    continue\r\n                num = None\r\n                if b.get('number') or (self.eqnum and b.get('number') is not False):\r\n                    self.eq += 1\r\n                    num = self.eq\r\n                story += [FormulaBlock(tex, size=self.S['p']['size'] + 1.6,\r\n                                       align=str(b.get('align') or 'center'),\r\n                                       number=num, stats=self.stats, warn=self.warn), Spacer(1, 7)]\r\n            elif t in ('ul', 'ol'):\r\n                story += self.bullet(b.get('items') or [], t == 'ol')\r\n            elif t == 'table':\r\n                story += self.table(b.get('head') or [], b.get('rows') or [], b.get('widths'))\r\n            elif t in ('box', 'callout'):\r\n                story += self.box(str(b.get('kind') or 'tip'), str(b.get('text') or ''),\r\n                                  str(b.get('title') or ''))\r\n            elif t == 'code':\r\n                story += self.code(b.get('text') or '', str(b.get('lang') or ''))\r\n            elif t == 'quote':\r\n                story += [Rich('「' + str(b.get('text') or '') + '」', font=FONTS['cn'],\r\n                               size=self.S['p']['size'] - 0.4, leading=self.S['p']['leading'],\r\n                               color=colors.HexColor('#4a5568'), indent=12, stats=self.stats),\r\n                          Spacer(1, 7)]\r\n            elif t == 'hr':\r\n                story += [Spacer(1, 3), _Rule(self.S['accent']), Spacer(1, 6)]\r\n            elif t in ('pagebreak', 'pb'):\r\n                story.append(PageBreak())\r\n            elif t == 'answer':\r\n                if self.variant == 'student':\r\n                    continue           # 学生版整块隐藏（讲义/习题双版本的关键）\r\n                story += self.box('proof', str(b.get('text') or ''), str(b.get('title') or '答案'))\r\n            elif t == 'cols':\r\n                story += self.cols(b.get('cols') or b.get('items') or [],\r\n                                   b.get('widths'), float(b.get('gap') or 10))\r\n            elif t == 'side':\r\n                story += self.side(b.get('aside') or [], b.get('body') or [],\r\n                                   str(b.get('side') or 'right'), float(b.get('width') or 0.34),\r\n                                   float(b.get('gap') or 10))\r\n            elif t == 'card':\r\n                story += self.card(b.get('body') or b.get('blocks') or [],\r\n                                   str(b.get('title') or ''), str(b.get('tone') or 'plain'))\r\n            elif t == 'divider':\r\n                story += [PageBreak(), Spacer(1, 120)]\r\n                story += self.heading(str(b.get('text') or ''), 1)\r\n                story += [Spacer(1, 14), _Rule(self.S['accent']), PageBreak()]\r\n            elif t in ('spacer', 'gap'):\r\n                story.append(Spacer(1, float(b.get('h') or 8)))\r\n            else:\r\n                # 未知块不吞掉内容：按段落渲染，并记一条警告（沉默丢内容是最坏的）\r\n                self.warn.append('未知块类型 %r 已按段落渲染' % t)\r\n                txt = str(b.get('text') or '')\r\n                if txt:\r\n                    story += [self.rich(txt), Spacer(1, 5)]\r\n        return story\r\n\r\n\r\nclass _Rule(Flowable):\r\n    def __init__(self, color, width=1.0):\r\n        Flowable.__init__(self)\r\n        self.color = color\r\n        self.width = width\r\n        self.height = 2\r\n\r\n    def wrap(self, aw, ah):\r\n        self._aw = aw\r\n        return (aw, self.height)\r\n\r\n    def draw(self):\r\n        self.canv.setStrokeColor(self.color)\r\n        self.canv.setLineWidth(self.width)\r\n        self.canv.line(0, 1, self._aw, 1)\r\n\r\n\r\n# ══════════════════════════════════════════════════════════════════════════\r\n# 5.5 HTML → blocks（2026-11-13 调研结论落地的部分）\r\n#\r\n# 【为什么只能走这条路】沙箱没有 DOM，三條候选全部**真装真跑**过：\r\n#   · xhtml2pdf  —— 装不上：`Can't find a pure Python 3 wheel for 'lxml>=6.0.0'`\r\n#                   （pyodide 自带 lxml 5.2.1，xhtml2pdf 要 ≥6，没有 wasm 轮子）\r\n#   · fpdf2.write_html —— 连 import 都失败：`cannot import name 'HTTPSHandler' from urllib.request'`\r\n#                   （它的 image_parsing 依赖 CPython 的 urllib HTTPSHandler，pyodide 里没有）\r\n#   · 唯一可行：**自己把 HTML 解析成 blocks**（lxml 可用），再喂给上面这套矢量引擎。\r\n# 好处不只是\"能用\"：公式仍然走 TextPath（真矢量），中文仍然是文字层 —— 另两个库都做不到。\r\n# 边界（必须说清楚，别让人以为这是浏览器）：\r\n#   · 不跑 CSS 布局（没有 float/flex/grid、没有选择器样式表）；div/section 只当\"容器递归\"\r\n#   · 行内只保留文字（strong/em/code 的**字形格式**丢弃，但内容一字不丢）\r\n#   · <img> 直接跳过并记 warning（矢量层 PDF 不塞位图；要图请先用 app.doc.pdf 或转成公式）\r\n# ══════════════════════════════════════════════════════════════════════════\r\nHTML_BLOCK_TAGS = {'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'p', 'ul', 'ol', 'li', 'table',\r\n                   'pre', 'blockquote', 'hr', 'div', 'section', 'article', 'header',\r\n                   'footer', 'main', 'figure', 'figcaption', 'dl', 'body'}\r\nHTML_SKIP_TAGS = {'script', 'style', 'head', 'meta', 'link', 'svg', 'iframe', 'noscript'}\r\n\r\n\r\ndef _norm_text(s):\r\n    \"\"\"HTML 里的空白归一：连续空白压成一个空格，保留中文全角空格。\"\"\"\r\n    return re.sub(r'[ \\t\\r\\f\\v]+', ' ', str(s or '')).strip()\r\n\r\n\r\ndef _inline_text(el):\r\n    \"\"\"一个元素的\"行内文字\"：递归取 text/tail，块级子元素由调用方另起一行。\r\n\r\n    为什么不用 text_content()：它会把 <br> 和块级子元素的内容**粘成一行**，\r\n    表格单元格/多段 div 会糊成一坨。这里按下标走 children，遇到块级子元素就断开。\r\n    \"\"\"\r\n    parts = [_norm_text(el.text)]\r\n    for ch in el:\r\n        tag = (ch.tag or '').lower() if isinstance(ch.tag, str) else ''\r\n        if tag in HTML_SKIP_TAGS:\r\n            pass\r\n        elif tag == 'br':\r\n            parts.append('\\n')\r\n        elif tag in ('strong', 'em', 'b', 'i', 'code', 'span', 'a', 'sup', 'sub', 'small', 'mark'):\r\n            parts.append(_inline_text(ch))            # 行内：内容拼进去，格式丢弃\r\n        elif tag in HTML_BLOCK_TAGS:\r\n            parts.append('\\n' + _inline_text(ch) + '\\n')\r\n        else:\r\n            parts.append(_inline_text(ch))\r\n        parts.append(_norm_text(ch.tail))\r\n    return ''.join([p for p in parts if p])\r\n\r\n\r\ndef _table_block(el):\r\n    head, rows = [], []\r\n    for tr in el.iter('tr'):\r\n        cells = []\r\n        for c in tr:\r\n            tag = (c.tag or '').lower() if isinstance(c.tag, str) else ''\r\n            if tag in ('td', 'th'):\r\n                cells.append(_inline_text(c).replace('\\n', ' ').strip())\r\n        if not cells:\r\n            continue\r\n        if not head and tr.getparent() is not None and any(\r\n                (x.tag or '').lower() == 'th' for x in tr if isinstance(x.tag, str)):\r\n            head = cells\r\n        else:\r\n            rows.append(cells)\r\n    # 列数取最大，短行补齐（reportlab 对不等长行会报错）\r\n    ncol = max([len(head)] + [len(r) for r in rows] or [0])\r\n    if ncol <= 0:\r\n        return None\r\n    fix = lambda r: (r + [''] * ncol)[:ncol]\r\n    return {'t': 'table', 'head': fix(head) if head else [], 'rows': [fix(r) for r in rows]}\r\n\r\n\r\ndef _list_block(el, ordered):\r\n    items = []\r\n    for li in el.findall('li'):\r\n        txt = _inline_text(li).replace('\\n', ' ').strip()\r\n        if txt:\r\n            items.append(txt)\r\n    return {'t': 'ol' if ordered else 'ul', 'items': items} if items else None\r\n\r\n\r\ndef _walk_blocks(node, out, warns, depth=0):\r\n    if depth > 24:                      # 防病态嵌套\r\n        return\r\n    for el in node:\r\n        tag = (el.tag or '').lower() if isinstance(el.tag, str) else ''\r\n        if not tag or tag in HTML_SKIP_TAGS:\r\n            continue\r\n        if tag == 'img':\r\n            src = str(el.get('src') or '')[:60]\r\n            warns.append('HTML 里的 <img> 已跳过（矢量层 PDF 不塞位图）：' + src)\r\n        elif tag in ('h1', 'h2', 'h3', 'h4', 'h5', 'h6'):\r\n            lvl = 3 if tag in ('h4', 'h5', 'h6') else int(tag[1])\r\n            out.append({'t': 'h%d' % lvl, 'text': _inline_text(el).replace('\\n', ' ').strip()})\r\n        elif tag == 'p':\r\n            txt = _inline_text(el).strip()\r\n            if txt:\r\n                out.append({'t': 'p', 'text': txt})\r\n        elif tag in ('ul', 'ol'):\r\n            b = _list_block(el, tag == 'ol')\r\n            if b:\r\n                out.append(b)\r\n        elif tag == 'table':\r\n            b = _table_block(el)\r\n            if b:\r\n                out.append(b)\r\n        elif tag == 'pre':\r\n            code = el.find('code')\r\n            src = (code if code is not None else el)\r\n            out.append({'t': 'code', 'text': ''.join(src.itertext()).rstrip('\\n')})\r\n        elif tag == 'blockquote':\r\n            txt = _inline_text(el).strip()\r\n            if txt:\r\n                out.append({'t': 'quote', 'text': txt})\r\n        elif tag == 'hr':\r\n            out.append({'t': 'hr'})\r\n        elif tag in ('div', 'section', 'article', 'header', 'footer', 'main', 'figure',\r\n                     'figcaption', 'dl', 'li', 'body'):\r\n            inner = _inline_text(el).strip()\r\n            if inner and '\\n' not in inner.strip() and not list(el):\r\n                out.append({'t': 'p', 'text': inner})\r\n            else:\r\n                _walk_blocks(el, out, warns, depth + 1)\r\n        else:\r\n            inner = _inline_text(el).strip()\r\n            if inner:\r\n                out.append({'t': 'p', 'text': inner})\r\n    return out\r\n\r\n\r\ndef html_to_blocks(html_text, warns=None):\r\n    \"\"\"HTML → blocks。解析失败就给一条可行动的错，不吞。\"\"\"\r\n    warns = warns if warns is not None else []\r\n    txt = str(html_text or '').strip()\r\n    if not txt:\r\n        return []\r\n    try:\r\n        from lxml import html as _lxml_html\r\n    except Exception as e:\r\n        raise SystemExit('pdfvec: 解析 HTML 需要 lxml（app.env.manage 装 lxml 即可）：%s' % e)\r\n    try:\r\n        doc = _lxml_html.fromstring(txt)\r\n    except Exception as e:\r\n        raise SystemExit('pdfvec: HTML 解析失败（%s）——请检查标签是否闭合' % str(e)[:80])\r\n    blocks = _walk_blocks(doc, [], warns)\r\n    if not blocks:\r\n        warns.append('HTML 解析后没有任何块级内容（可能整篇都在 <script>/<style> 里？）')\r\n    return blocks\r\n\r\n\r\n# ══════════════════════════════════════════════════════════════════════════\r\n# 6. 封面 + 入口\r\n# ══════════════════════════════════════════════════════════════════════════\r\ndef cover_story(doc_meta, styles):\r\n    \"\"\"封面用 onPage 直接画（满版色块 + 标题），不进 story —— 这样它不受页边距约束。\"\"\"\r\n    def paint(c, doc):\r\n        c.saveState()\r\n        w, h = doc.pagesize\r\n        c.setFillColor(styles['accent'])\r\n        c.rect(0, h - 118 * mm, w, 118 * mm, stroke=0, fill=1)\r\n        c.setFont(FONTS['cn'], 24)\r\n        c.setFillColor(colors.white)\r\n        title = doc_meta.get('title') or ''\r\n        y = h - 62 * mm\r\n        for i in range(0, len(title), 16):\r\n            c.drawString(24 * mm, y, title[i:i + 16])\r\n            y -= 12 * mm\r\n        if doc_meta.get('subtitle'):\r\n            c.setFont(FONTS['cn'], 12)\r\n            c.setFillColor(colors.Color(1, 1, 1, alpha=0.86))\r\n            c.drawString(24 * mm, y - 2 * mm, str(doc_meta['subtitle'])[:40])\r\n        c.setFillColor(colors.HexColor('#374151'))\r\n        c.setFont(FONTS['cn'], 10)\r\n        y2 = 60 * mm\r\n        for line in (doc_meta.get('meta') or []):\r\n            c.drawString(24 * mm, y2, str(line)[:48])\r\n            y2 -= 7 * mm\r\n        c.restoreState()\r\n    return paint\r\n\r\n\r\ndef render_file(job_path, out_path):\r\n    \"\"\"读 job.json 渲染 PDF，返回 stats（也写到 out_path+'.stats.json'，便于外部读）。\r\n\r\n    job = {\r\n      \"meta\": {\"title\",\"subtitle\",\"author\",\"subject\",\"paper\",\"meta\":[\"…\"]},\r\n      \"options\": {\"variant\":\"teacher|student\",\"toc\":true,\"eqnum\":false,\r\n                  \"watermark\":\"\",\"fontset\":\"cm|katex\",\"accent\":\"#2b6cb0\",\"cnSize\":10.5},\r\n      \"fonts\": {\"cn\":\"/work/SimHei.ttf\",\"mono\":\"…/DejaVuSansMono.ttf\",\"katexDir\":\"/work/.pdfvec/fonts\"},\r\n      \"blocks\": [ ... ]\r\n    }\r\n    \"\"\"\r\n    with open(job_path, 'r', encoding='utf-8') as f:\r\n        job = json.load(f)\r\n    meta = job.get('meta') or {}\r\n    opt = job.get('options') or {}\r\n    fonts = job.get('fonts') or {}\r\n\r\n    fstate = setup_fonts(fonts.get('cn'), fonts.get('mono'),\r\n                         str(opt.get('fontset') or 'cm'), fonts.get('katexDir'))\r\n\r\n    th = theme_of(opt.get('theme'), str(opt.get('accent') or ''))\r\n    accent = th['accent']\r\n    cn_size = float(opt.get('cnSize') or 10.5) * float(th.get('size') or 1.0)\r\n    S = build_styles(accent, cn_size)\r\n    S['theme'] = th\r\n    S['box'] = th.get('box') or {}\r\n    warns = []\r\n\r\n    pagesize = PAPERS.get(str(meta.get('paper') or 'A4'), A4)\r\n    m = opt.get('marginMm') or [18, 18, 20, 18]\r\n    margins = (float(m[0]) * mm, float(m[1]) * mm, float(m[2]) * mm, float(m[3]) * mm)\r\n\r\n    doc_meta = dict(meta)\r\n    doc_meta['pagesize'] = pagesize\r\n    doc_meta['cover_first'] = bool(meta.get('cover'))\r\n\r\n    tmpl = Doc(out_path, meta=doc_meta, styles=S,\r\n               header_text=str(opt.get('header') or meta.get('header') or meta.get('title') or ''),\r\n               footer=bool(opt.get('footer', True)),\r\n               watermark=str(opt.get('watermark') or ''),\r\n               margins=margins)\r\n    if doc_meta['cover_first']:\r\n        tmpl.addPageTemplates([PageTemplate(id='cover', frames=[Frame(\r\n            tmpl.leftMargin, tmpl.bottomMargin, tmpl.width, tmpl.height, id='cf')],\r\n            onPage=cover_story(meta, S)),\r\n            PageTemplate(id='main', frames=[Frame(\r\n                tmpl.leftMargin, tmpl.bottomMargin, tmpl.width, tmpl.height, id='body')],\r\n                onPage=tmpl._deco)])\r\n\r\n    builder = Builder(S, variant=str(opt.get('variant') or 'teacher'),\r\n                      eqnum=bool(opt.get('eqnum')), warn=warns)\r\n    # 布局原语要知道可用宽度（Frame 宽度在 build 前就定了，这里直接量）\r\n    builder._frame_width = tmpl.width\r\n\r\n    # 目录：{t:'toc'} 处插入真正的 TableOfContents（多遍构建后页码自动回填）\r\n    toc_placeholder = TableOfContents()\r\n    toc_placeholder.levelStyles = [\r\n        ParagraphStyle('toc1', fontName=FONTS['cn'], fontSize=cn_size + 0.6, leading=cn_size * 2.1,\r\n                       leftIndent=0, firstLineIndent=0, textColor=colors.HexColor('#1f2937')),\r\n        ParagraphStyle('toc2', fontName=FONTS['cn'], fontSize=cn_size - 0.4, leading=cn_size * 1.9,\r\n                       leftIndent=14, firstLineIndent=0, textColor=colors.HexColor('#374151')),\r\n        ParagraphStyle('toc3', fontName=FONTS['cn'], fontSize=cn_size - 1.0, leading=cn_size * 1.8,\r\n                       leftIndent=28, firstLineIndent=0, textColor=colors.HexColor('#4b5563')),\r\n    ]\r\n    blocks = job.get('blocks') or []\r\n    # html / markdown 输入：先转成 blocks，再走同一条排版管线（公式仍是矢量路径）\r\n    raw_md = job.get('markdown')\r\n    raw_html = job.get('html')\r\n    if not blocks and raw_md:\r\n        try:\r\n            import markdown as _md\r\n            raw_html = _md.markdown(str(raw_md), extensions=['tables', 'fenced_code'])\r\n        except Exception:\r\n            raise SystemExit('pdfvec: markdown 输入需要 markdown 包（app.env.manage 装 markdown）')\r\n    if not blocks and raw_html:\r\n        blocks = html_to_blocks(raw_html, warns)\r\n        if not blocks:\r\n            raise SystemExit('pdfvec: HTML 里没有可渲染的块级内容')\r\n    story = []\r\n    if doc_meta['cover_first']:\r\n        story += [Spacer(1, 1), PageBreak()]\r\n    for b in blocks:\r\n        if isinstance(b, dict) and str(b.get('t') or b.get('type') or '').lower() == 'toc':\r\n            story += [Rich('目 录', font=FONTS['cn'], size=cn_size + 6, leading=(cn_size + 6) * 1.8,\r\n                           color=S['accent'], align='center', stats=builder.stats),\r\n                      Spacer(1, 8), toc_placeholder, PageBreak()]\r\n        else:\r\n            story += builder.build([b])\r\n\r\n    if not any(isinstance(f, Flowable) for f in story):\r\n        raise SystemExit('pdfvec: blocks 为空，没什么可渲染的')\r\n\r\n    tmpl.multiBuild(story, canvasmaker=NumberedCanvas)\r\n    # ★ 统计必须在 multiBuild 之后读：写在前面读到的是\"还没画任何东西\"的 0，\r\n    # 第一版就这么报了 curves=0 / formulas=0（数字自检成了摆设）。\r\n    total = {'curves': builder.stats['curves'], 'formulas': builder.stats['formulas']}\r\n\r\n    # ── 自检：结构层（有没有图片对象 / 页数 / 字节数）──\r\n    with open(out_path, 'rb') as f:\r\n        raw = f.read()\r\n    latin = raw.decode('latin-1', errors='ignore')\r\n    pages = len(re.findall(r'/Type\\s*/Page[^s]', latin))\r\n    images = len(re.findall(r'/Subtype\\s*/Image', latin))\r\n    stats = {\r\n        'ok': images == 0,\r\n        'pages': pages,\r\n        'images': images,\r\n        'curves': total['curves'],\r\n        'formulas': total['formulas'],\r\n        'bytes': len(raw),\r\n        'fonts': fstate,\r\n        'warnings': warns[:20],\r\n    }\r\n    with open(out_path + '.stats.json', 'w', encoding='utf-8') as f:\r\n        json.dump(stats, f, ensure_ascii=False)\r\n    return stats\r\n\r\n\r\nif __name__ == '__main__':\r\n    if len(sys.argv) < 3:\r\n        raise SystemExit('用法: pdfvec.py <job.json> <out.pdf>')\r\n    print(json.dumps(render_file(sys.argv[1], sys.argv[2]), ensure_ascii=False))\r\n"});if(!b.ok)return{ok:!1,error:"写渲染引擎失败："+String(b.error||"")};const u={meta:{title:c.title,subtitle:c.subtitle||"",author:c.author||"",subject:c.subject||"",paper:c.paper||"A4",cover:!!c.cover,meta:[]},options:{variant:"student"===c.variant?"student":"teacher",toc:!1!==c.toc,eqnum:!!c.eqnum,watermark:c.watermark||"",fontset:"katex"===c.fontset?"katex":"cm",theme:c.theme||"classic",accent:c.accent||"",cnSize:Number(c.cnSize)||10.5,header:c.header||c.title,footer:!1!==c.footer},fonts:{cn:g.path||"",mono:"",katexDir:""},blocks:c.blocks||[],html:c.html||"",markdown:c.markdown||""},w=await n(i,{text:JSON.stringify(u)});if(!w.ok)return{ok:!1,error:"写作业描述失败："+String(w.error||"")};const x=["import json, os","g = {'__name__': 'pdfvec'}","exec(compile(open('"+o+"').read(), 'pdfvec.py', 'exec'), g)","st = g['render_file']('"+i+"', '"+f+"')","json.dumps(st, ensure_ascii=False)"].join("\n"),S=await t(x,24e4);if(!S.ok)return{ok:!1,error:"渲染失败："+String(S.error||"").split("\n").filter(Boolean).slice(-6).join(" / ").slice(0,400)};let T=null;const v=await a(f+".stats.json",2e4);if(v.ok&&v.text)try{T=JSON.parse(String(v.text))}catch(F){T=null}if(!T)try{const r=String(S.output||"").trim().split("\n").pop()||"{}",e=JSON.parse(r);e&&"number"==typeof e.pages&&(T=e)}catch(F){T=null}const k=await a(f),y=k.ok?String(k.b64||""):"";let N="";if(y){const r=String(c.saveTitle||c.title||"文档").replace(/[\\/:*?"<>|]/g,"_").slice(0,60)+".pdf",e=await l(r,{b64:y});e.ok&&e.id&&(N=e.id)}const z=!!N||!!y;return{ok:z||!!T&&!!T.ok,stats:T||void 0,artifactId:N||void 0,workPath:f,error:z?void 0:"PDF 已渲染但没能取回字节（工作区里应仍有 "+f+"）"}}export{c as renderPdfVector};
